use datom_codec::{Actualizing,Budget,Potential}; use std::{env,fs,os::unix::net::UnixStream}; use shared_translator::{FrameReading,FrameWriting,Restorable,Signal,Signalizable};
fn budget()->Budget{Budget{remaining:1_000_000,reader:protos::ReaderBudget{remaining:1_000_000},depth:0,maximum_depth:1024}}
fn main()->Result<(),Box<dyn std::error::Error>>{let mut a=env::args().skip(1);let registry_path=a.next().ok_or("REGISTRY_PATH")?;let name=a.next().ok_or("NAME")?;let text=a.next().ok_or("DATOM")?;let mut b=budget();let r=herdr_nexus_translator::registry::decode(&fs::read_to_string(registry_path)?,&mut b).map_err(|e|format!("{e:?}"))?;let place=herdr_nexus_translator::registry::select(&r,&name).map_err(|e|format!("{e:?}"))?;let mut p=Potential::<meta_signal_herdr_nexus::Query>::from(text);let q=p.actualize(&mut budget()).map_err(|e|format!("{e:?}"))?;let mut s=UnixStream::connect(std::path::Path::new(&place.directory.0).join("herdr-meta.sock"))?;s.write_frame(&q.signalize()?,shared_translator::FrameCapacity::default())?;let body=s.read_frame(shared_translator::FrameCapacity::default())?;let r:meta_signal_herdr_nexus::Response=Signal::from(Vec::from(body)).restore()?;println!("{}",shared_translator::encode(&r));if !matches!(r,meta_signal_herdr_nexus::Response::Configured(meta_signal_herdr_nexus::ConfigureOutcome::Succeeded)){std::process::exit(1)}Ok(())}
